result.reserve(points.size());

for (size_t i = 0; i < points.size(); ++i) {
    const auto& pt = points[i];
    if (pt.x >= range.Min.x && pt.x <= range.Max.x &&
        pt.y >= range.Min.y && pt.y <= range.Max.y &&
        pt.z >= range.Min.z && pt.z <= range.Max.z) {
        result.push_back(i);
    }
}

return result;

